import { colorStyleParts } from "../../../styles/color";
export function getBadgeColors(color, variant) {
    const colorParts = colorStyleParts[color];
    switch (variant) {
        case "default":
        case "status":
            return `${colorParts.base}`;
        case "light":
            return `${colorParts.muted} text-white/60`;
        case "outline":
            return `border ${colorParts.border} ${colorParts.text}`;
        default:
            return "";
    }
}
