export function multiAction(node, initialActions) {
    let instances = [];
    function mountActions(actionsList) {
        if (!actionsList || actionsList.length === 0)
            return [];
        return actionsList.map(([action, params]) => action(node, params));
    }
    function destroyInstances() {
        instances.forEach(inst => inst?.destroy?.());
        instances = [];
    }
    instances = mountActions(initialActions);
    return {
        update(newActions) {
            destroyInstances();
            instances = mountActions(newActions);
        },
        destroy() {
            destroyInstances();
        }
    };
}
